import{_ as s,l,o as e,c as i,v as r,p as n,x as t,d,i as E,S as p}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"闭包与最小覆盖","description":"","frontmatter":{"title":"闭包与最小覆盖","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/fd-closure-min-cover.md","filePath":"cs/fd-closure-min-cover.md","lastUpdated":1789023840000}'),F={name:"cs/fd-closure-min-cover.md"};function c(h,a,m,B,A,_){const o=l("Mermaid");return e(),i("div",null,[a[1]||(a[1]=r('<h1 id="闭包与最小覆盖" tabindex="-1">闭包与最小覆盖 <a class="header-anchor" href="#闭包与最小覆盖" aria-label="Permalink to &quot;闭包与最小覆盖&quot;">​</a></h1><div class="epigraph"><p>属性闭包用 FD 当产生式扩张；正则覆盖去掉冗余依赖与多余属性，3NF 合成吃的就是这一份最小合同。</p><footer>—— 据 Bernstein 合成算法；Ramakrishnan and Gehrke；Ullman 对闭包与覆盖的整理</footer></div><p><a href="/cs/armstrong-axioms">上一课</a>给出 FD 的可靠完备公理。本课不重推三条。缺口是算法：给定 \\(F\\) 与 \\(X\\)，是否 \\(X \\to Y\\)？给定 \\(F\\)，有没有更小的 \\(G\\) 与 \\(F\\) 等价？主干 3NF 合成「按正则覆盖建表」，进阶把闭包与最小覆盖写清。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(X^+\\)：从 \\(X\\) 出发，反复把已被决定的属性并进来，直到不动。\\(Y \\subseteq X^+\\) 当且仅当 \\(F \\models X \\to Y\\)。这是蕴含的决策过程，复杂度对 \\(|F|\\) 与属性数多项式。缺口还包括覆盖：若 \\(F\\) 与 \\(G\\) 蕴含相同依赖，则等价。最小（正则）覆盖：右部单属性、无多余 FD、无左部多余属性。</p><p>多余：一条 FD 可被其余推出则删。左部多余属性：从左部拿掉仍蕴含原 FD。求正则覆盖是 3NF 合成的预处理，否则会建出多余表或漏表。</p><p><span class="marginnote">闭包也可对整个 \\(F\\) 谈 \\(F^+\\)（所有被蕴含的 FD），那是指数大的集合，不能枚举；算法永远用属性闭包当探针，不物化 \\(F^+\\)。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>属性闭包：结果集 \\(Z \\leftarrow X\\)；扫描 \\(F\\)，若左部 \\(\\subseteq Z\\) 则 \\(Z \\leftarrow Z \\cup\\) 右部；重复至不变。实现可用计数器避免每轮全扫。候选键：找 \\(X \\subseteq U\\) 使 \\(X^+ = U\\) 且真子集不行——枚举子集仍指数，但属性少时可行；启发式从决定因素入手。</p><p>正则覆盖：先拆右部为单属性；删多余 FD；对每条左部试删属性并用闭包检验。结果不唯一，但都与 \\(F\\) 等价。</p>',10)),(e(),n(p,null,{default:t(()=>[E(o,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E5%B1%9E%E6%80%A7%E9%9B%86%20X%22%5D%20--%3E%20CL%5B%22%E7%94%A8%20F%20%E6%89%A9%E5%BC%A0%E9%97%AD%E5%8C%85%22%5D%0A%20%20CL%20--%3E%20Q%5B%22Y%20%E6%98%AF%E5%90%A6%E5%9C%A8%20X%20%E9%97%AD%E5%8C%85%E4%B8%AD%22%5D%0A%20%20F%5B%22FD%20%E9%9B%86%20F%22%5D%20--%3E%20MC%5B%22%E6%AD%A3%E5%88%99%E8%A6%86%E7%9B%96%20G%22%5D%0A%20%20MC%20--%3E%20TNF%5B%22%E5%90%8E%E8%AF%BE%3A%203NF%20%E5%90%88%E6%88%90%E5%B7%B2%E5%9C%A8%E4%B8%BB%E5%B9%B2%22%5D%0A%20%20MC%20--%3E%20LOSS%5B%22%E4%B8%8B%E4%B8%80%E8%AF%BE%3A%20%E6%97%A0%E6%8D%9F%E4%B8%8E%E4%BF%9D%E6%8C%81%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>BCNF 检验：对覆盖中每条 \\(X \\to A\\)，检查 \\(X\\) 是否超键（\\(X^+ = U\\)）。3NF：允许 \\(A\\) 为主属性的例外。这些判定都把本课当子程序。查询优化不用闭包搜连接顺序；依赖理论站在模式层，与 Selinger 课分开。</p><p>错误的覆盖（漏 FD）会让分解看起来已保持依赖，运行时却出现违反——约束课的运行时检查补的是实例，不是 \\(F\\) 写错。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证明 3NF 合成的正确性定理全文，不引入无损连接判定的tableau——下一课。也不对 SQL 唯一约束如何近似 FD 再展开。</p><p>后课默认：\\(F\\) 以正则覆盖呈现；键用闭包检验。无损分解与依赖保持是分解质量的两条独立轴。</p><p>闭包是探针；覆盖是合同的最简写法。二者都比「列出 \\(F^+\\)」可算。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>属性闭包判定 FD 蕴含；正则覆盖与 \\(F\\) 等价且无多余。</li><li>3NF/BCNF 检验把闭包当子程序。</li><li>下一课：分解何时无损、何时保持依赖。</li><li>出处：Bernstein；Ullman；Ramakrishnan and Gehrke。</li></ul>',9))])}const f=s(F,[["render",c]]);export{D as __pageData,f as default};
